/* source: portfolio-back.js */
/* Right-click goes back one portfolio level; Shift-right-click keeps native menus. */
(()=>{
 let last=-Infinity;
 document.addEventListener('contextmenu',event=>{
  if(event.shiftKey||event.target.closest?.('input,textarea,[contenteditable="true"]'))return;
  event.preventDefault();
  const now=performance.now();if(now-last<400)return;last=now;
  if(window.portfolioGoBack?.())return;
  // Prefer the actual previous document (including scroll/hash state).
  // A directly opened page has a deterministic portfolio-home fallback.
  if(history.length>1)history.back();
  else location.href='zhong-xi-han-portfolio-preview.html';
 });
})();
;

/* source: project-details-editorial.js */
/* Scope enhancements to each dynamically opened case study, including fallbacks. */
(()=>{
 function decorate(root){
  root.querySelectorAll('.project-inline-details table').forEach(table=>{
   if(table.parentElement.classList.contains('case-table-scroll'))return;
   const frame=document.createElement('div');frame.className='case-table-scroll';
   frame.tabIndex=0;frame.setAttribute('role','region');
   frame.setAttribute('aria-label',(table.closest('section')?.querySelector('h2')?.textContent||'项目规范')+'表格，可横向滚动');
   table.before(frame);frame.append(table);
  });
 }
 const observer=new MutationObserver(records=>{if(records.some(r=>r.addedNodes.length))decorate(document);});
 observer.observe(document.body,{childList:true,subtree:true});decorate(document);
})();
;

/* source: inline-project-details.js */
window.inlineProjectDetails={"shan-ye-details.html":"<div class=\"process\"><section><h2>01 / 主题立项</h2><p>围绕花果乌龙茶的日常饮用场景，将桂花与山楂转化为可识别的图形，结合小猫角色，让包装在品牌识别与趣味表达之间建立联系。</p></section>\n<section><h2>02 / 制作过程</h2><p>先统一品牌字形和小猫形象，再根据两种花果主题确定配色及图案。将正面视觉延展到侧面、底部信息区和礼盒展开示意，并通过正面、开盒与系列组合样机检查应用效果。</p><div class=\"gallery dieline-gallery\"><figure><div class=\"dieline-layout\"><div class=\"dieline-crop\"><img src=\"shan-ye-lai-xin/hawthorn-dieline-selected.png.webp\" alt=\"山楂乌龙礼盒新版展开规范\" loading=\"lazy\"></div><aside class=\"dieline-info\"><h3>尺寸规范</h3><p>成品尺寸（内径）<br>300 × 220 × 60 mm</p><dl><dt>上盖</dt><dd>300 × 220 mm</dd><dt>后翻墙</dt><dd>60 mm</dd><dt>底盒</dt><dd>300 × 220 mm</dd><dt>前墙</dt><dd>60 mm</dd><dt>侧边墙</dt><dd>60 mm</dd></dl><h3>线型图例</h3><p class=\"dieline-key\"><span class=\"cut-line\"></span>切割线（刀模线）</p><p class=\"dieline-key\"><span class=\"fold-line\"></span>折叠线（压痕线）</p></aside></div><figcaption>山楂乌龙 · 礼盒展开规范</figcaption></figure><figure><div class=\"dieline-layout\"><div class=\"dieline-crop\"><img src=\"shan-ye-lai-xin/osmanthus-dieline-selected.png.webp\" alt=\"桂花乌龙礼盒新版展开规范\" loading=\"lazy\"></div><aside class=\"dieline-info\"><h3>尺寸规范</h3><p>成品尺寸（内径）<br>300 × 220 × 60 mm</p><dl><dt>上盖</dt><dd>300 × 220 mm</dd><dt>后翻墙</dt><dd>60 mm</dd><dt>底盒</dt><dd>300 × 220 mm</dd><dt>前墙</dt><dd>60 mm</dd><dt>侧边墙</dt><dd>60 mm</dd></dl><h3>线型图例</h3><p class=\"dieline-key\"><span class=\"cut-line\"></span>切割线（刀模线）</p><p class=\"dieline-key\"><span class=\"fold-line\"></span>折叠线（压痕线）</p></aside></div><figcaption>桂花乌龙 · 礼盒展开规范</figcaption></figure></div></section>\n<section><h2>03 / 设计思路</h2><p>斜切字形与几何化角色形成统一的棱角语言。小猫分别手捧桂花与山楂，传达产品主题；黄色桂花款与粉色山楂款形成清晰的系列区分。产品名称作为正面视觉重点，品牌名与标语辅助识别，底面集中组织产品信息。</p><img class=\"wide\" src=\"shan-ye-lai-xin/yellow-box/logo-guidelines.png.webp\" alt=\"山野来信标志与视觉规范\" loading=\"lazy\"></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>展开图中的正面、侧面与底面需要兼顾连续视觉和信息可读性。当前方案通过统一品牌字形、保留侧面识别与独立底部信息区组织版面。具体生产问题及打样记录尚未提供，不作为已完成成果陈述。</p><p class=\"pending\">展开图为概念结构示意，非生产刀模。建议成品内径为 300 × 220 × 60 mm；尺寸、锁口、出血和产品信息须由印厂校核并打样确认。</p></section>\n<section><h2>05 / 成品展示</h2><div class=\"gallery\"><figure><img src=\"shan-ye-lai-xin/hawthorn-poster-selected.png.webp\" alt=\"山楂乌龙产品海报\" loading=\"lazy\"><figcaption>山楂乌龙 · 产品海报</figcaption></figure><figure><img src=\"shan-ye-lai-xin/03-products.png.webp\" alt=\"桂花乌龙产品海报\" loading=\"lazy\"><figcaption>桂花乌龙 · 产品海报</figcaption></figure><figure><img src=\"shan-ye-lai-xin/yellow-box/front.png.webp\" alt=\"桂花乌龙礼盒正面样机\" loading=\"lazy\"><figcaption>桂花乌龙 · 正面</figcaption></figure><figure><img src=\"shan-ye-lai-xin/yellow-box/open-perspective-v2.png.webp\" alt=\"山野来信礼盒开盒效果\" loading=\"lazy\"><figcaption>礼盒开盒展示</figcaption></figure></div></section><section><h2>06 / 周边设计</h2><p>延续黄粉配色、棱角小猫与花果图形，应用于纸质手提袋、帆布袋、杯垫、贴纸和书签。</p><figure><img class=\"wide\" src=\"shan-ye-lai-xin/merchandise-v1.png.webp\" alt=\"山野来信手提袋帆布袋杯垫贴纸书签周边样机\" loading=\"lazy\"><figcaption>山野来信 · 周边概念样机</figcaption></figure></section></div>","half-a-whisper-details.html":"<div class=\"process\"><section><h2>01 / 主题立项</h2><p>围绕香水与香氛的日常表达，以“半句花语”建立轻盈、含蓄的品牌形象。</p></section>\n<section><h2>02 / 制作过程</h2><p>现有方案将品牌字标与拼贴图形应用于瓶身标签、礼盒和手提袋。以下三视图展示正面、侧面与背面的视觉关系。</p><figure><img src=\"half-a-whisper/perfume-three-views.png.webp\" alt=\"香水瓶 · 正面、侧面与背面\" loading=\"lazy\"><figcaption>香水瓶 · 正面、侧面与背面</figcaption></figure><figure><img src=\"half-a-whisper/gift-box-three-views.png.webp\" alt=\"紫色礼盒 · 正面、侧面与背面\" loading=\"lazy\"><figcaption>紫色礼盒 · 正面、侧面与背面</figcaption></figure><figure><img src=\"half-a-whisper/bag-three-views.png.webp\" alt=\"手提袋 · 正面、侧面与背面\" loading=\"lazy\"><figcaption>手提袋 · 正面、侧面与背面</figcaption></figure></section>\n<section><h2>03 / 设计思路</h2><p>以不规则剪纸字形表现品牌个性，淡紫撕纸色块与黑白网点形成层次。米白纸材和玻璃瓶身保留轻盈感，统一的图形组合贯穿瓶身、礼盒与手提袋。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>不同载体的面积与比例各异，需要兼顾品牌识别和留白。三视图通过调整字标大小及拼贴位置，保持正面信息清晰，并将辅助图形延续至侧面和背面。</p></section>\n<section><h2>05 / 成品展示</h2><figure><img src=\"half-a-whisper/brand-family-cover.png.webp\" alt=\"半句花语 · 品牌包装系列\" loading=\"lazy\"><figcaption>半句花语 · 品牌包装系列</figcaption></figure><figure><img src=\"half-a-whisper/poster-perfume-collage-logo.png.webp\" alt=\"半句花语 · 香水宣传海报\" loading=\"lazy\"><figcaption>半句花语 · 香水宣传海报</figcaption></figure></section></div>","zaolou-details.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>以开平煲仔饭为对象，围绕柴火瓦煲与侨乡文化建立餐饮品牌识别。选题从传统烹饪场景和品牌建设需求切入，将地域记忆转化为可延展的视觉系统。</p><figure><img src=\"zaolou/source/p-04.jpg.webp\" alt=\"项目背景\" loading=\"lazy\"><figcaption>项目背景</figcaption></figure><figure><img src=\"zaolou/source/p-05.jpg.webp\" alt=\"项目意义\" loading=\"lazy\"><figcaption>项目意义</figcaption></figure></section>\n<section><h2>02 / 制作过程</h2><p>通过文献、问卷、实地与网络调研梳理品牌现状及消费需求，再以思维导图和用户体验地图组织设计方向。随后探索标志、字体、食材图形和吉祥物草图，确定视觉规范，并延展至包装、宣传及餐饮应用。</p><figure><img src=\"zaolou/source/p-07.jpg.webp\" alt=\"调研分析与方法\" loading=\"lazy\"><figcaption>调研分析与方法</figcaption></figure><figure><img src=\"zaolou/source/p-08.jpg.webp\" alt=\"设计思路与思维导图\" loading=\"lazy\"><figcaption>设计思路与思维导图</figcaption></figure><figure><img src=\"zaolou/source/p-12.jpg.webp\" alt=\"用户体验地图\" loading=\"lazy\"><figcaption>用户体验地图</figcaption></figure><figure><img src=\"zaolou/source/p-16.jpg.webp\" alt=\"标志、字体、辅助图形与角色草图\" loading=\"lazy\"><figcaption>标志、字体、辅助图形与角色草图</figcaption></figure><figure><img src=\"zaolou/source/p-25.jpg.webp\" alt=\"餐盒与包装结构展开设计\" loading=\"lazy\"><figcaption>餐盒与包装结构展开设计</figcaption></figure></section>\n<section><h2>03 / 设计思路</h2><p>品牌名“灶楼”结合柴火灶与开平碉楼意象，以“以灶为魂，以楼为根”组织定位。标志融合煲仔饭本体、火焰、砖砌柴火灶和印章式衬托；配色从锅巴、米饭与烹饪场景提取，辅助图形延展为食材、器具、火焰和地域建筑。吉祥物“小煲 X-bao”进一步增加亲近感。</p><figure><img src=\"zaolou/source/p-13.jpg.webp\" alt=\"品牌定位与命名释义\" loading=\"lazy\"><figcaption>品牌定位与命名释义</figcaption></figure><figure><img src=\"zaolou/source/p-14.jpg.webp\" alt=\"色彩规范\" loading=\"lazy\"><figcaption>色彩规范</figcaption></figure><figure><img src=\"zaolou/source/p-17.jpg.webp\" alt=\"标志构成与设计说明\" loading=\"lazy\"><figcaption>标志构成与设计说明</figcaption></figure><figure><img src=\"zaolou/source/p-18.jpg.webp\" alt=\"标志制图与应用规范\" loading=\"lazy\"><figcaption>标志制图与应用规范</figcaption></figure><figure><img src=\"zaolou/source/p-19.jpg.webp\" alt=\"食材、器具及地域建筑辅助图形\" loading=\"lazy\"><figcaption>食材、器具及地域建筑辅助图形</figcaption></figure><figure><img src=\"zaolou/source/p-20.jpg.webp\" alt=\"火焰与重复纹样设计\" loading=\"lazy\"><figcaption>火焰与重复纹样设计</figcaption></figure><figure><img src=\"zaolou/source/p-21.jpg.webp\" alt=\"辅助图形组合\" loading=\"lazy\"><figcaption>辅助图形组合</figcaption></figure><figure><img src=\"zaolou/source/p-22.jpg.webp\" alt=\"小煲 X-bao 角色设计\" loading=\"lazy\"><figcaption>小煲 X-bao 角色设计</figcaption></figure><figure><img src=\"zaolou/source/p-23.jpg.webp\" alt=\"角色表情设计\" loading=\"lazy\"><figcaption>角色表情设计</figcaption></figure></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>调研资料指出，现有餐饮品牌存在品牌建设被忽略、视觉同质化、文化符号表面化，以及系统设计与用户体验缺失等问题。方案以开平地域线索与柴火烹饪符号形成差异化识别，并统一标志、色彩、字体和辅助图形，再通过用户体验地图及多场景应用组织整套品牌系统。</p><figure><img src=\"zaolou/source/p-09.jpg.webp\" alt=\"调研发现的设计痛点\" loading=\"lazy\"><figcaption>调研发现的设计痛点</figcaption></figure><figure><img src=\"zaolou/source/p-10.jpg.webp\" alt=\"设计机会与改进方向\" loading=\"lazy\"><figcaption>设计机会与改进方向</figcaption></figure></section>\n<section><h2>05 / 成品展示</h2><figure><img src=\"zaolou/poster-wall-mockup-v1.png.webp\" alt=\"灶楼煲仔饭店内海报应用样机\" loading=\"lazy\"><figcaption>灶楼 · 店内海报应用概念样机</figcaption></figure><figure><img src=\"zaolou/packaging-mockup-no-food-v1.png.webp\" alt=\"灶楼煲仔饭无食物包装系列样机\" loading=\"lazy\"><figcaption>灶楼 · 煲仔饭包装系列概念样机</figcaption></figure><p>展示包装、餐具、文创物料、宣传海报、线上页面及门店应用，呈现品牌视觉在不同接触点上的延展效果。</p><figure><img src=\"zaolou/source/p-35.jpg.webp\" alt=\"餐盒、纸盒、外带纸袋与保温袋包装\" loading=\"lazy\"><figcaption>餐盒、纸盒、外带纸袋与保温袋包装</figcaption></figure><figure><img src=\"zaolou/source/p-33.jpg.webp\" alt=\"餐具与桌面物料\" loading=\"lazy\"><figcaption>餐具与桌面物料</figcaption></figure><figure><img src=\"zaolou/source/p-34.jpg.webp\" alt=\"文创与携带物料\" loading=\"lazy\"><figcaption>文创与携带物料</figcaption></figure><figure><img src=\"zaolou/source/p-24.jpg.webp\" alt=\"品牌文创应用设计\" loading=\"lazy\"><figcaption>品牌文创应用设计</figcaption></figure><figure><img src=\"zaolou/source/p-26.jpg.webp\" alt=\"宣传海报设计\" loading=\"lazy\"><figcaption>宣传海报设计</figcaption></figure><figure><img src=\"zaolou/source/p-27.jpg.webp\" alt=\"餐饮宣传视觉\" loading=\"lazy\"><figcaption>餐饮宣传视觉</figcaption></figure><figure><img src=\"zaolou/source/p-28.jpg.webp\" alt=\"线上视觉设计\" loading=\"lazy\"><figcaption>线上视觉设计</figcaption></figure><figure><img src=\"zaolou/source/p-29.jpg.webp\" alt=\"线上页面应用样机\" loading=\"lazy\"><figcaption>线上页面应用样机</figcaption></figure><figure><img src=\"zaolou/source/p-30.jpg.webp\" alt=\"门头与室内应用\" loading=\"lazy\"><figcaption>门头与室内应用</figcaption></figure><figure><img src=\"zaolou/source/p-31.jpg.webp\" alt=\"空间视觉应用\" loading=\"lazy\"><figcaption>空间视觉应用</figcaption></figure><figure><img src=\"zaolou/source/p-32.jpg.webp\" alt=\"宣传物料展示\" loading=\"lazy\"><figcaption>宣传物料展示</figcaption></figure></section>\n</div>","hello-paw.html":"<div class=\"process\">\n\n<section><h2>01 / 主题立项</h2><p>围绕四款日用纸品建立统一的品牌包装语言，以动物角色和产品配色区分用途，同时保持品牌字标和信息层级的一致。</p></section>\n<section><h2>02 / 设计思路</h2><p>红、黄、蓝、绿四色水彩肌理与米白留白构成系列识别。动物造型融入字母 P，让品牌字标与产品角色形成关联；具体迭代记录待补充。</p></section>\n<section class=\"logo-spec\"><h2>03 / 四款 Logo 使用规范</h2><p>四款以动物形象的 P 为核心识别：竖向笔画构成身体，字母上部转化为头部，尾巴与耳朵进一步表达角色。HELLO / PAW 两行字标、A 内爪印与圆点共同维持系列一致性。</p><div class=\"gallery\"><figure><h3>小狗 / 抽纸</h3><div class=\"logo-guide\"><img src=\"hello-paw/logo-dog-imported.png.webp\" alt=\"小狗 / 抽纸标准 Logo\" loading=\"lazy\"></div><figcaption>完整组合标志 · 保持原稿比例、点位及动物特征<br><a href=\"hello-paw/logo-dog-imported.png.webp\" rel=\"noopener\">查看标准稿 ↗</a></figcaption><p>小狗 P：垂耳与前伸的鼻口形成亲近的侧脸，P 的竖笔构成身体，小尾巴强化动物形象；红色对应抽纸。</p></figure>\n<figure><h3>小熊 / 卷纸</h3><div class=\"logo-guide\"><img src=\"hello-paw/logo-bear-imported.png.webp\" alt=\"小熊 / 卷纸标准 Logo\" loading=\"lazy\"></div><figcaption>完整组合标志 · 保持原稿比例、点位及动物特征<br><a href=\"hello-paw/logo-bear-imported.png.webp\" rel=\"noopener\">查看标准稿 ↗</a></figcaption><p>小熊 P：耳部轮廓与饱满的头部区分小狗，黑色眼鼻和微笑保留简洁表情；黄色对应卷纸。</p></figure>\n<figure><h3>猫咪 / 湿纸巾</h3><div class=\"logo-guide\"><img src=\"hello-paw/logo-cat-imported.png.webp\" alt=\"猫咪 / 湿纸巾标准 Logo\" loading=\"lazy\"></div><figcaption>完整组合标志 · 保持原稿比例、点位及动物特征<br><a href=\"hello-paw/logo-cat-imported.png.webp\" rel=\"noopener\">查看标准稿 ↗</a></figcaption><p>猫咪 P：三角耳和短胡须是识别重点，头部沿 P 的上部展开，竖笔与尾巴形成身体；蓝色对应湿纸巾。</p></figure>\n<figure><h3>刺猬 / 洗脸巾</h3><div class=\"logo-guide\"><img src=\"hello-paw/logo-hedgehog-imported.png.webp\" alt=\"刺猬 / 洗脸巾标准 Logo\" loading=\"lazy\"></div><figcaption>完整组合标志 · 保持原稿比例、点位及动物特征<br><a href=\"hello-paw/logo-hedgehog-imported.png.webp\" rel=\"noopener\">查看标准稿 ↗</a></figcaption><p>刺猬 P：锯齿状黑色背刺与前伸的脸部构成角色，保留 P 的竖向骨架及小尾巴；绿色对应洗脸巾。</p></figure></div>\n<h3>比例与组合</h3><p>将完整标志作为一个整体等比缩放，不单独调整 HELLO、P、A、W、爪印或圆点的位置。画布白边不计入标志尺寸；以实际图形外接边界测量宽高。四款外接比例略有差异，应用时统一图形总宽与视觉中心，不强行拉成相同比例。</p>\n<h3>安全留白</h3><p>设标志实际图形总宽为 W，定义 x = W / 10。四周最小净空建议为 1x，文字、功能图标、裁切线与封边不得进入该区域。上方示意虚线框表示标志保护区，实际制作应按图形边界计算，而非按图片白边计算。</p>\n<h3>最小使用尺寸 · 建议值</h3><p>完整组合标志印刷宽度建议不小于 30 mm，屏幕显示宽度建议不小于 160 px。小尺寸优先检查爪印、眼睛、猫咪胡须与装饰圆点的清晰度。低于建议尺寸不直接缩小使用，应另行制作经确认的简化版本。该值需结合印刷材料和工艺打样确认。</p>\n<h3>颜色与背景</h3><p>四款采用本次导入的图片：动物 P 保留米白色，HELLO、A、W 使用对应包装色，黑色细节不变。猫咪图片包含蓝色与米白色光晕，为图片自带效果，不作为标准配色或印刷规范。抽纸、卷纸、湿纸巾、洗脸巾分别使用红、黄、蓝、绿产品底色；确保米白字形与背景可辨，黑色表情和爪印清楚。原始白底稿保留备查，透明底版不带白色矩形。正式印刷色值、白墨及专色须由矢量原稿与打样确认，不用网页取色代替印刷标准。</p>\n<h3>禁止使用</h3><p>禁止非等比拉伸、镜像、随意旋转、重排两行字标、替换字体、改变动物对应产品、删除爪印或圆点、添加描边和发光效果，以及把完整标志跨越开口、折线或封合区。包装透视须将完整标志作为同一平面投射，不逐字变形。</p>\n<p class=\"pending\">当前展示为透明底位图；生产前需整理矢量母版，并复核最小细节。以上规范为设计建议，非已验证的印刷参数。</p></section>\n<section class=\"spec\"><h2>04 / 包装规范与结构参考</h2><p class=\"pending\">以下四款展开图为参考尺寸与贴版区域模板，不是经工厂验证的生产刀模，也未包含完整最终印刷图稿。实际膜宽、折线、封合余量、开口及工艺须结合材料、设备和实物打样校核，禁止直接用于生产。</p>\n<figure><h3>抽纸 / 结构与贴版规范</h3><img src=\"hello-paw/portfolio/facial-tissue/dieline.svg\" alt=\"HELLO PAW 抽纸包装结构参考展开图\" loading=\"lazy\"><figcaption><a href=\"hello-paw/portfolio/facial-tissue/dieline.svg\" rel=\"noopener\">查看完整抽纸规范图 ↗</a></figcaption></figure>\n<figure><h3>卷纸 / 结构与贴版规范</h3><img src=\"hello-paw/portfolio/toilet-roll/dieline.svg\" alt=\"HELLO PAW 卷纸包装结构参考展开图\" loading=\"lazy\"><figcaption><a href=\"hello-paw/portfolio/toilet-roll/dieline.svg\" rel=\"noopener\">查看完整卷纸规范图 ↗</a></figcaption></figure>\n<figure><h3>湿纸巾 / 结构与贴版规范</h3><img src=\"hello-paw/portfolio/wet-wipes/dieline.svg\" alt=\"HELLO PAW 湿纸巾包装结构参考展开图\" loading=\"lazy\"><figcaption><a href=\"hello-paw/portfolio/wet-wipes/dieline.svg\" rel=\"noopener\">查看完整湿纸巾规范图 ↗</a></figcaption></figure>\n<figure><h3>洗脸巾 / 结构与贴版规范</h3><img src=\"hello-paw/portfolio/face-towel/dieline.svg\" alt=\"HELLO PAW 洗脸巾包装结构参考展开图\" loading=\"lazy\"><figcaption><a href=\"hello-paw/portfolio/face-towel/dieline.svg\" rel=\"noopener\">查看完整洗脸巾规范图 ↗</a></figcaption></figure>\n</section>\n<section><h2>05 / 成品样机</h2><div class=\"gallery\"><img src=\"hello-paw/portfolio/facial-tissue/mockup.png.webp\" alt=\"HELLO PAW 抽纸包装样机\" loading=\"lazy\"><img src=\"hello-paw/portfolio/toilet-roll/mockup.png.webp\" alt=\"HELLO PAW 卷纸包装样机\" loading=\"lazy\"><img src=\"hello-paw/portfolio/wet-wipes/mockup-v3.png.webp\" alt=\"HELLO PAW 湿纸巾包装样机\" loading=\"lazy\"><img src=\"hello-paw/portfolio/face-towel/mockup.png.webp\" alt=\"HELLO PAW 洗脸巾包装样机\" loading=\"lazy\"></div></section>\n</div>","mugwort.html":"<div class=\"process\"><section><h2>01 / 主题立项</h2><p>以艾草为研究对象，从历史文化、植物特征与日常应用切入，探索如何将分散的中医药资料转化为清晰、亲近的科普视觉表达。通过图文结合的信息结构，让读者从熟悉的植物进入中医药文化的阅读。</p><div class=\"gallery\"><figure><img loading=\"lazy\" src=\"mugwort-research-topic.png.webp\" alt=\"选题来源\"><figcaption>选题来源</figcaption></figure></div></section><section><h2>02 / 制作过程</h2><p>资料调研 → 思维导图分类 → 图文占位草图 → 主体线稿 → AI 风格与配色探索 → 板绘上色及二次修改 → 成品整合。先尝试多种图文布局，再用深绿色信息块与浅色背景确定主次关系；主体插画逐步完成叶片色块、明暗层次和肌理。</p><div class=\"gallery\"><figure><img loading=\"lazy\" src=\"mugwort-mind-map.png.webp\" alt=\"信息分类与思维导图\"><figcaption>信息分类与思维导图</figcaption></figure><figure><img loading=\"lazy\" src=\"mugwort-layout-process.png.webp\" alt=\"版式占位草图与布局方案\"><figcaption>版式占位草图与布局方案</figcaption></figure><figure><img loading=\"lazy\" src=\"mugwort-painting-process.png.webp\" alt=\"主体插画的线稿、上色与肌理过程\"><figcaption>主体插画的线稿、上色与肌理过程</figcaption></figure></div></section><section><h2>03 / 设计思路</h2><p>以思维导图建立内容层级，将基础知识、中药特点、主要成分、现代研究等内容组织成信息模块。以草本绿色作为主要视觉线索，深绿强化信息层级，浅黄绿色辅助组织背景。植物插画保留叶片轮廓和层叠关系，再以平面色块与颗粒肌理进行视觉转译，使主体插画成为阅读入口。</p><div class=\"gallery\"><figure><img loading=\"lazy\" src=\"mugwort-sketch-final.png.webp\" alt=\"主体线稿与终稿对照\"><figcaption>主体线稿与终稿对照</figcaption></figure></div></section><section><h2>04 / 遇到的问题与解决</h2><p>插画风格选择：需要把写实植物参考转化为适合科普版面的动漫平面画风，并找到合适的配色方向。解决方法是先寻找参考图并绘制线稿，再使用即梦 AI 将写实参考转换为动漫平面风格，参考生成后的颜色进行板绘上色与二次修改。AI 用于风格和配色探索，线稿与最终上色由作者完成。<br><br>资料整理：通过思维导图将资料划分为基础知识、主要功效、现代研究、中药特点、主要成分和特殊人群注意事项，再转化为版面中的信息模块。具体资料整理困难及处理细节待进一步补充。</p><div class=\"gallery\"><figure><img loading=\"lazy\" src=\"mugwort-ai-process.png.webp\" alt=\"即梦 AI 风格探索记录\"><figcaption>即梦 AI 风格探索记录</figcaption></figure></div></section><section><h2>05 / 成品展示</h2><p>两张艾草科普可视化成品，将植物主体插画、分组知识与绿色信息层级整合，呈现从资料整理、版式探索到板绘制作的成果。</p><div class=\"gallery\"><figure><img loading=\"lazy\" src=\"mugwort-visualization-01.jpg.webp\" alt=\"艾草可视化成品一\"><figcaption>艾草可视化成品一</figcaption></figure><figure><img loading=\"lazy\" src=\"mugwort-visualization-02.jpg.webp\" alt=\"艾草可视化成品二\"><figcaption>艾草可视化成品二</figcaption></figure></div></section></div>","redtail-details.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>以赤尾避孕套平面广告为设计对象，从中途干涩这一沟通痛点切入，探索如何将锁水、顺滑的产品诉求转化为直观的视觉意象。</p></section>\n<section><h2>02 / 制作过程</h2><p>先探索沙漠仙人掌与透明薄膜的组合，再转向安全套外形的泳池意象。使用 AI 生成视觉草图，结合图像编辑调整形状、人物与版面，完成广告文字及品牌信息的整合。</p><figure><img src=\"redtail/cactus-concept.png.webp\" alt=\"赤尾创意草图：仙人掌意象与AI探索记录\" loading=\"lazy\"><figcaption>创意方向一 · 仙人掌与透明薄膜</figcaption></figure><figure><img src=\"redtail/pool-concept.png.webp\" alt=\"赤尾创意草图：泳池意象与AI探索记录\" loading=\"lazy\"><figcaption>创意方向二 · 水彩泳池意象</figcaption></figure></section>\n<section><h2>03 / 设计思路</h2><p>仙人掌方向通过干燥地面与锁水意象建立反差，但写实形象中的刺容易产生不适联想，产品关联也不够清晰。泳池方向采用明亮蓝色、水波与漂浮圈，结合四周的瓷砖边界建立容器与安全感的隐喻，使表达更轻松、直观。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>AI 草图未能准确生成所需的安全套外形，泳池轮廓需要进一步手动调整。过程记录提出了减少水面装饰、调整人物等改进方向；完成稿将人物改为女性，重新安排广告语的位置，并整合品牌标志和产品图。AI 用于前期视觉探索，完成稿仍需进行人工编辑与排版。</p><p class=\"note\">本页展示设计创意及原始过程记录；“2小时锁水”等表述来自项目题目与广告文案，不作为独立验证的产品性能结论。</p></section>\n<section><h2>05 / 成品展示</h2><figure><img src=\"redtail/final-comparison.png.webp\" alt=\"赤尾平面广告初稿与完成稿对照\" loading=\"lazy\"><figcaption>初稿与完成稿 · 人物、广告语与品牌信息调整</figcaption></figure><figure><img src=\"redtail-condom-poster.jpg.webp\" alt=\"赤尾避孕套平面广告成品\" loading=\"lazy\"><figcaption>赤尾 · 泳池主题海报成品</figcaption></figure></section>\n</div>","giant-show.html":"<div class=\"process\"><section><h2>01 / 风格说明</h2><p>这套作品具有酸性设计的视觉特征：高亮荧光绿与蓝色形成强烈反差，尖锐、不规则的字形营造紧张、躁动的节奏。巨人脸部用几何线段概括，结合虚线路径、等高线与点阵，让人物像一张可探索的地图。</p><p>标题是画面中的视觉图形，底部信息则采用规则矩形分区与清晰的无衬线排字。自由、激烈的主体与理性的网格形成对比，使实验感与信息可读性并存。</p></section>\n<section><h2>02 / 字体规范</h2><p>以下为这套视觉的建议应用规范。标题使用现有定制字标，不将其识别为某款现成字体。原海报信息字体名称尚未确认，替代字体需以实际排版对照为准。</p><table><thead><tr><th>用途</th><th>字体与形式</th><th>使用规则</th></tr></thead><tbody><tr><td>主标题 / Logo</td><td>原始 THE GIANT SHOW 尖刺字标</td><td>保留三行结构、白色填充和蓝色描边。等比缩放，不重排、拉伸或遮挡尖刺。</td></tr><tr><td>英文活动信息</td><td>建议 Arial Regular 或 Helvetica Regular</td><td>使用大写英文、蓝色文字。左右内边距保持一致，不压缩字形以强行塞满信息框。</td></tr><tr><td>日期与数字</td><td>沿用信息字体</td><td>以字号和空间区分层级，避免不规则字距影响阅读。</td></tr><tr><td>中文说明</td><td>建议思源黑体 / Noto Sans SC</td><td>正文采用常规字重，与英文无衬线风格协调。</td></tr></tbody></table><p>建议层级：主要活动信息为正文的 1.5 至 2 倍，辅助标注为正文的 0.7 至 0.85 倍。字标周围至少留出其宽度 5% 的净空。小尺寸应用若尖刺、描边或字腔无法辨认，应放大字标或使用普通文字名称。印刷字号与细线粗细须通过实际打样确认。</p></section>\n<section><h2>03 / Logo 与周边</h2><p>帆布袋以大面积荧光绿和蓝色提带突出远距离识别。明信片分别使用完整字标、点阵图形和简洁地址版式，延续海报的同一套语言。</p><img src=\"giant-show-merchandise-v1.png.webp\" alt=\"巨人展帆布袋与明信片概念效果图\"></section><section><h2>04 / 海报场景样机</h2><h3>入口双灯箱</h3><img src=\"giant-show-lightbox-v1.png.webp\" alt=\"巨人展双海报入口灯箱样机\" loading=\"lazy\"><h3>装框展墙</h3><img src=\"giant-show-gallery-v1.png.webp\" alt=\"巨人展双海报混凝土展墙样机\" loading=\"lazy\"></section></div>","lin-chang-fa-hui.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>围绕“临场发挥”主题，在规则的模块与自由的流动纹理之间形成对比，表现秩序与即兴共存的视觉状态。</p></section>\n<section><h2>02 / 制作过程</h2><p>从原海报中提取黑白块面、实验字形、细线和流动纹理，应用于周边与导视。通过 AI 辅助效果图展示材质和空间关系，再根据反馈调整袋子下方的图形，并将入口立式导视、墙面展区导视分别独立展示。</p></section>\n<section><h2>03 / 设计思路</h2><p>大尺度字形建立视觉识别，流动纹理打破几何块面的稳定感。周边保持统一的黑白配色；导视以清晰的箭头和中英文信息为主，识别图形为辅，兼顾展览氛围与方向提示。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>袋子下方原有边框和线条使信息显得复杂，因此去掉该区域的线条与外框，只保留“临场发挥”四个字。导视分别呈现独立效果，检查牌面、文字和图形的透视关系，使版面与实体表面保持一致。</p></section>\n<section><h2>05 / 成品展示</h2><h3>周边设计</h3><figure><img class=\"wide\" src=\"lin-chang-fa-hui-merchandise-v3.png.webp\" alt=\"临场发挥帆布袋、明信片、折页与挂绳周边效果图\" loading=\"lazy\"><figcaption>帆布袋、明信片、折页与挂绳；袋子下方仅保留主题文字。</figcaption></figure><h3>小型导视设计</h3><div class=\"gallery\"><figure><img src=\"lin-chang-fa-hui-entrance-v1.png.webp\" alt=\"入口立式导视独立效果图\" loading=\"lazy\"><figcaption>入口立式导视 / ENTRANCE</figcaption></figure><figure><img src=\"lin-chang-fa-hui-wall-sign-v1.png.webp\" alt=\"展区01墙面导视独立效果图\" loading=\"lazy\"><figcaption>展区墙面导视 / EXHIBITION 01</figcaption></figure></div></section>\n<section><h2>06 / 海报场景样机</h2><figure><img class=\"wide\" src=\"lin-chang-fa-hui-gallery-mockup-v1.png.webp\" alt=\"临场发挥两款海报并排装框展墙样机\" loading=\"lazy\"><figcaption>装框展墙样机 · 两款海报并排展示</figcaption></figure><figure><img class=\"wide\" src=\"lin-chang-fa-hui-street-mockup-v1.png.webp\" alt=\"临场发挥两款海报街头混凝土墙面张贴样机\" loading=\"lazy\"><figcaption>街头张贴样机 · 纸张肌理与墙面场景</figcaption></figure></section>\n<section><h2>07 / 纸品周边</h2><p>将黑白实验字形与流动纹理延展至吊牌、明信片和系列小卡，使用不同局部构图建立统一而有变化的纸品系列。</p><figure><img class=\"wide\" src=\"lin-chang-fa-hui-stationery-v1.png.webp\" alt=\"临场发挥吊牌、明信片正反面和系列收藏小卡样机\" loading=\"lazy\"><figcaption>吊牌、明信片与系列小卡 · 周边概念样机</figcaption></figure></section>\n</div>","insect-world.html":"<div class=\"process\"><section><h2>01 / 主题立项</h2><p>围绕“微小生物，丰富世界”的展览主题，以昆虫的形态差异建立系列视觉，让甲虫、蝴蝶与蜻蜓成为具有识别度的图形。</p></section>\n<section><h2>02 / 制作过程</h2><p>以现有海报为基础，提取昆虫图案、几何网格和大尺度文字，将其延展至帆布袋、纸质手提袋、明信片与贴纸。周边采用 AI 辅助概念效果图呈现设计方向，原海报保持不变。</p></section>\n<section><h2>03 / 设计思路</h2><p>用圆形、椭圆与花瓣状模块组织昆虫的身体和翅膀，强调对称与重复。玫红文字和色块在炭黑、米色中形成视觉重点，细密网点和纸张肌理延续复古印刷质感。</p><p>帆布袋将昆虫图案与标题组成中央印花，纸质手提袋采用连续网格图案与玫红侧面。三款明信片分别展示甲虫、蝴蝶与蜻蜓，贴纸提取单个昆虫造型，适配不同载体。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p class=\"pending\">实际制作中的问题与迭代记录待补充。周边目前为概念展示，尚未进行生产打样。</p></section>\n<section><h2>05 / 成品展示</h2><h3>周边设计</h3><p>帆布袋、纸质手提袋、三款明信片与昆虫贴纸。</p><img src=\"insect-world-merchandise.png.webp\" alt=\"昆虫世界展帆布袋、纸质手提袋、明信片与贴纸周边概念效果图\" loading=\"lazy\"><h3>纸品与徽章系列</h3><p>帆布袋、三款昆虫明信片、两款书签与三款圆形徽章。</p><img src=\"insect-world-merchandise-v2.png.webp\" alt=\"昆虫世界帆布袋、蝴蝶甲虫蜻蜓明信片、书签和徽章系列样机\" loading=\"lazy\"></section></div>","keyvisual.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>以北京理工大学珠海学院设计与艺术学院 2026 届毕业设计展为背景，围绕“留‘流’下印迹”展开视觉设计。“流”谐音年份中的“6”，将毕业年份与灵感流动、创意流变相联系；“印迹”则指向毕业生的作品和成长痕迹，让毕业展成为青春创作的纪念。</p><p>项目以统一的视觉语言串联六个参展专业，形成从主视觉海报、动态传播到现场物料的整体形象。指导老师：李静。</p></section>\n<section><h2>02 / 制作过程</h2><h3>专业元素与色彩建立</h3><p>提取六个专业英文名称的首字母，形成 A（工艺美术）、V（视觉传达设计）、P（产品设计）、D（数字媒体艺术）、E（环境设计）、C（服装与服饰设计）的流体字母元素。背景选用紫蓝与深色体系：#2B1666、#111825、#062175、#752A77。</p><div class=\"gallery\"><img src=\"imprint-proposal-03.png.webp\" alt=\"六个专业的流体字母元素设计\" loading=\"lazy\"><img src=\"imprint-proposal-04.png.webp\" alt=\"主视觉背景色彩选取\" loading=\"lazy\"></div><h3>静态排版与延展制作</h3><p>方案中的 Illustrator 工作界面记录了道旗、专业顶条展板、横幅和横向主视觉的排版制作。通过图层整理专业图形素材，再将统一的图形与信息系统适配不同物料比例。</p><img src=\"imprint-proposal-33.png.webp\" alt=\"Illustrator 排版与图层整理制作记录\" loading=\"lazy\"><h3>动态视觉制作</h3><p>制作记录展示了 After Effects 的多图层合成与时间线，以及视频剪辑界面。动态成果包含总展主视觉与专业主视觉，将静态流体图形延伸为动态表达。</p><img src=\"imprint-proposal-34.png.webp\" alt=\"动态海报合成和视频编辑制作记录\" loading=\"lazy\"></section>\n<section><h2>03 / 设计思路</h2><h3>以流体形态连接“流”与“6”</h3><p>将流动的图形融入数字“6”，呼应 2026 的年份信息，也隐喻设计创作的开放性。专业视觉则使用对应字母构成不同形态，在共同的流体语言中保留各专业的识别差异。</p><h3>冷暖对比与深色空间</h3><p>紫、蓝、橙、红的渐变与高饱和荧光色相互碰撞，营造科技感和空间感；深色背景让明亮的流体图形更突出，同时通过冷暖色变化表达不同专业的多元性。</p><h3>动态形态与静态信息的平衡</h3><p>活动标题采用大字号无衬线字体，毕业展名称、主题、时间与专业信息通过字号和颜色建立层级。中英双语专业名称兼顾信息识别，简洁的“印迹”文字与流动图形形成动静对比，回应记录成长与展示创意的双重价值。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p class=\"pending\">具体困难、调整方案和解决过程待作者补充。此处保留与艾草详情页一致的章节结构，不编造项目经历。</p></section>\n<section><h2>05 / 成品展示</h2><p>静态海报、动态视觉与现场延展应用。</p><div class=\"gallery\">\n<img src=\"imprint-static-01.png.webp\" alt=\"印迹静态海报一\" loading=\"lazy\"><img src=\"imprint-static-02.png.webp\" alt=\"印迹静态海报二\" loading=\"lazy\">\n<video src=\"imprint-graduation-main-motion.mp4\" controls preload=\"none\" playsinline aria-label=\"总展动态海报\"></video><video src=\"imprint-graduation-disciplines-motion.mp4\" controls preload=\"none\" playsinline aria-label=\"专业动态海报\"></video>\n<img src=\"imprint-extension-01-armband.png.webp\" alt=\"臂章应用\" loading=\"lazy\"><img src=\"imprint-extension-02-event-kit.png.webp\" alt=\"展览物料\" loading=\"lazy\"><img src=\"imprint-extension-03-site-banners.png.webp\" alt=\"现场旗帜\" loading=\"lazy\"><img src=\"imprint-extension-04-site-fascia.png.webp\" alt=\"现场门头\" loading=\"lazy\">\n</div><h3>六个专业海报</h3><div class=\"gallery\"><img src=\"imprint-proposal-11.png.webp\" alt=\"视觉传达、环境与服装专业海报\" loading=\"lazy\"><img src=\"imprint-proposal-12.png.webp\" alt=\"产品、数字媒体与工艺美术专业海报\" loading=\"lazy\"></div><h3>展览物料设计</h3><div class=\"gallery\"><img src=\"imprint-proposal-13.png.webp\" alt=\"道旗、横幅、签名板与证件设计总览\" loading=\"lazy\"><img src=\"imprint-proposal-17.png.webp\" alt=\"各专业顶条展板设计\" loading=\"lazy\"></div><h3>空间与周边应用展示</h3><p class=\"caption\">以下为方案提供的应用展示与效果图，不作为实际落地完成的证明。</p><div class=\"gallery\"><img src=\"imprint-proposal-24.png.webp\" alt=\"总展海报空间应用效果图\" loading=\"lazy\"><img src=\"imprint-proposal-26.png.webp\" alt=\"专业海报室内应用效果图\" loading=\"lazy\"><img src=\"imprint-proposal-30.png.webp\" alt=\"入口横幅应用展示\" loading=\"lazy\"><img src=\"imprint-proposal-31.png.webp\" alt=\"帆布袋应用效果图\" loading=\"lazy\"><img src=\"imprint-proposal-32.png.webp\" alt=\"证件挂绳应用效果图\" loading=\"lazy\"><img src=\"imprint-proposal-27.png.webp\" alt=\"道旗应用效果图\" loading=\"lazy\"></div></section>\n</div>","uiux.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>“小绿书 / GREEN BOOK”是一款二手书交易小程序的界面设计方案。以知识共享和图书再利用为主题，围绕图书发布、在线下单、订单管理以及搜索浏览，设计买卖双方的操作路径。</p><p>方案还包含分类筛选、浏览记录、评价评分，以及多种支付方式和按书籍成色提供价格建议等功能设想。这些内容属于设计方案，不代表已上线的服务。</p></section>\n<section><h2>02 / 制作过程</h2><h3>信息架构与流程梳理</h3><p>以首页、卖书、购物车和我的四个一级入口组织功能，再展开搜索、分类、扫码或手动输入 ISBN、订单管理、客服与历史记录等二级页面。</p><div class=\"gallery\"><img src=\"green-book-architecture.png.webp\" alt=\"小绿书信息架构\" loading=\"lazy\"><img src=\"green-book-flow-01.png.webp\" alt=\"小绿书功能流程图\" loading=\"lazy\"></div><h3>低保真与页面连接</h3><p>PPT 展示了灰度低保真界面以及带连接线的页面流程。低保真以模块区分书籍列表、分类与操作区，页面连接图说明各入口与交易页面之间的跳转关系。</p><div class=\"gallery\"><img src=\"green-book-wireframes.png.webp\" alt=\"小绿书低保真界面\" loading=\"lazy\"><img src=\"green-book-flow-02.png.webp\" alt=\"小绿书界面跳转连接图\" loading=\"lazy\"></div><h3>高保真界面与样机</h3><p>将绿色品牌识别应用于按钮、图标状态及界面重点区域，形成买书、卖书和订单管理等高保真页面，再通过样机呈现完整界面系统。</p></section>\n<section><h2>03 / 设计思路</h2><h3>品牌与视觉规范</h3><p>Logo 以书本图标表达知识和资源共享，绿色呼应环保主题，圆润的手写风格字标传递亲切感。方案以 #4C7154 为主要绿色，并标注 #F7502F 等辅助色及部分元素的 60% 透明度设置。</p><p>设计参考 iOS 与 iPhone X，以 375 × 812 px 为逻辑画布，对应 1125 × 2436 px 的像素分辨率。图标未选中时使用线性形式，选中后转为面性图标并呈现绿色状态反馈。</p><h3>围绕任务组织界面</h3><p>搜索栏置顶，分类入口帮助用户按类别浏览。推荐书籍采用可左右滑动的大图展示，书籍列表集中呈现信息。底部四个导航入口提供稳定的功能切换路径。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><p>资料未记录具体迭代困难与用户测试结果。以下整理的是 PPT 中已有的交互应对设计。</p><h3>不同成色对应不同价格</h3><p>加入购物车时弹出成色与价格选择，让用户先明确购买规格，再进入结算。</p><h3>卖书信息录入与查询失败</h3><p>提供条形码扫描和手动输入 ISBN 两种入口。查询成功后进入下一页面，查询不到时使用弹窗提示。</p><h3>选择状态与结算反馈</h3><p>购物车选中商品后，圆形选择按钮变绿，同时结算按钮转为绿色可点击状态。管理入口支持批量删除或单本操作。</p><h3>退出下单页面的提醒</h3><p>方案在离开下单页面时提供提醒和继续下单选项。是否能改善完成率仍需验证，也应在后续测试中检查提醒是否打扰用户。</p></section>\n<section><h2>05 / 成品展示</h2><h3>整体界面系统</h3><div class=\"gallery\"><img src=\"green-book-04-interface-system-transparent.png.webp\" alt=\"GREEN BOOK 整体界面系统一\" loading=\"lazy\"><img src=\"green-book-05-interface-system.png.webp\" alt=\"GREEN BOOK 整体界面系统二\" loading=\"lazy\"></div></section>\n</div>","extended.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>《奇艺之旅》讲述小女孩京因绘画瓶颈而想放弃画画，意外捡到神秘书籍后，穿越至文艺复兴、印象派和立体主义等艺术时期。在冒险与学习中，她找回信心，重新拿起画笔。</p><p>项目来自书籍设计课程，也与作者自身的创作迷茫相联系。以京的视角引导读者接触艺术史，同时表达“画画最重要的是热爱画画的心”。</p></section>\n<section><h2>02 / 制作过程</h2><h3>故事与人物构思</h3><p>先确定时空冒险的基础剧情，再围绕整体设定、剧情和环境展开构思。京的早期形象为黑色短发、蓝色裙子与爱心发夹，后期改为黄色长发、红色裙子和泪痣，保留名为雪球的小黑猫。</p><h3>场景与分镜调整</h3><p>早期设计包含大图书馆与麦田，后期删去大图书馆，将书架放回家中，并以星空和草地替换麦田。分镜最初以大跨页为主，后期改用漫画格推进剧情，以大跨页展开环境描写。</p><h3>封面迭代与成稿</h3><p>PPT 展示了四版封面的迭代，以及分镜和成稿对照。创作过程中查阅不同艺术时期的名画，参考其色彩搭配与构图，将艺术场景融入京的冒险。</p><h3>书籍排版与装订</h3><p>课程实践涵盖开本、白书、版心、样章、字体字号测试和成书装订。成品采用骑马订与 200 克铜版纸。</p><p>成品尺寸：220 × 220 mm。</p></section>\n<section><h2>03 / 设计思路</h2><h3>艺术史融入冒险故事</h3><p>通过时空穿越让读者跟随京接触艺术作品与创作理念。文艺复兴阶段关注自然和人性的刻画，后续场景探索光影、色彩与几何化表达，让艺术风格参与环境叙事。</p><h3>阅读节奏与情感线索</h3><p>漫画格承接人物行动和对话，大跨页提供观察环境的空间。京从迷茫到重新拾起画笔的变化贯穿故事，使知识内容与创作情感相互呼应。</p></section>\n<section><h2>04 / 遇到的问题与解决</h2><h3>首次绘本创作的叙事难度</h3><p>问题：绘本需要同时处理剧情、对话、分镜与人物，实际难度超出最初预期。调整：确立京的创作瓶颈与寻找信心这一动机，并将分镜调整为漫画格推进剧情、跨页描写环境。</p><h3>主题反复调整与时间不足</h3><p>问题：前期不断变更主题，后期只剩一个多星期，出现明显赶工。应对：压缩内容，课程总结记录页数从二十多页删减为十四页，以完成第一本绘本为阶段目标。</p><h3>仍需改进的部分</h3><p>作者在课程总结中指出，成品仍存在场景转换突兀、开场铺垫不足、剧情不够清楚和色彩混乱等问题。这些是尚待改进的部分，不能写成已经解决。后续应更早确定主题与分镜，并预留叙事检查和统一配色的时间。</p></section>\n<section><h2>05 / 成品展示</h2><h3>封面、跨页与书籍细节</h3><div class=\"gallery\">\n<img src=\"wonder-journey-02-spread-transparent.png.webp\" alt=\"奇艺之旅成品展示 1\" loading=\"lazy\">\n<img src=\"wonder-journey-03-spread-transparent.png.webp\" alt=\"奇艺之旅成品展示 2\" loading=\"lazy\">\n<img src=\"wonder-journey-04-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 3\" loading=\"lazy\">\n<img src=\"wonder-journey-05-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 4\" loading=\"lazy\">\n<img src=\"wonder-journey-06-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 5\" loading=\"lazy\">\n<img src=\"wonder-journey-07-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 6\" loading=\"lazy\">\n<img src=\"wonder-journey-08-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 7\" loading=\"lazy\">\n<img src=\"wonder-journey-09-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 8\" loading=\"lazy\">\n<img src=\"wonder-journey-10-detail-transparent.png.webp\" alt=\"奇艺之旅成品展示 9\" loading=\"lazy\">\n</div></section></div>","illustration.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>以《聊斋志异·聂小倩》篇故事角色形象设计为毕业设计主题，探索如何将经典文学中的角色特质、明代服饰与民俗符号转化为当代年轻受众易于理解的视觉语言。项目从角色插画出发，延伸至文创物料与虚幻引擎场景，连接文本阅读、视觉观看和空间体验。</p><h3>调研与定位</h3><p>结合原著与传统服饰、首饰资料研读，开展案例分析、问卷调查及玉台寺实地考察。由此确立“古典志怪、传统新生、暗喻符号”三个关键词，以文学内涵为依据，而非仅复刻已有影视角色。</p><div class=\"gallery\"><img src=\"nie-defense-05.png.webp\" alt=\"文献、案例、实地与问卷调研\" loading=\"lazy\"><img src=\"nie-thesis-043.png.webp\" alt=\"古典志怪、传统新生、暗喻符号设计定位\" loading=\"lazy\"></div></section>\n<section><h2>02 / 制作过程</h2><h3>资料归纳与角色草图</h3><p>使用豆包与 DeepSeek 辅助资料归纳，围绕造型、色彩、道具、场景、服饰建立素材库。通过 AI 工具探索初步想法，再在 Procreate 中绘制精细草图与线稿，确定角色动作、服饰层次及道具关系。</p><div class=\"gallery\"><img src=\"nie-defense-08.png.webp\" alt=\"前期角色、服饰与道具草稿\" loading=\"lazy\"><img src=\"nie-defense-09.png.webp\" alt=\"寺庙场景与构图草稿\" loading=\"lazy\"></div><h3>配色探索与手绘成图</h3><p>利用即梦 AI、可灵等工具辅助草稿配色探索，确定整体色彩基调后，在 Photoshop 中进行手绘上色与细节完善。AI 参与的是构思和配色辅助，成图绘制与排版仍由作者完成。</p><div class=\"gallery\"><img src=\"nie-defense-10.png.webp\" alt=\"绘画过程中图层组织记录\" loading=\"lazy\"><img src=\"nie-defense-29.png.webp\" alt=\"硬切分绘画与服饰道具细节\" loading=\"lazy\"></div><h3>排版与周边延展</h3><p>将完成的插画导入 Illustrator，制作海报及周边，再用 InDesign 进行专册、展板和延展物料的规范化排版。成果包含系列海报、角色设计手册、明信片、书签与亚克力立牌。</p><h3>数字场景探索</h3><p>场景部分先用 Procreate 确定构图和动线，再在虚幻引擎 5 中搭建白模、配置材质与寺庙模型。结合 Substance 系列制作材质、SpeedTree 构建树木、Niagara 添加粒子效果，最后通过 DaVinci Resolve 进行输出画面的调色。</p><img src=\"nie-defense-48.png.webp\" alt=\"虚幻引擎竹林场景与模型搭建展示\" loading=\"lazy\"></section>\n<section><h2>03 / 设计思路</h2><h3>传统色彩与硬切分语言</h3><p>从传统画作、明代服饰和参考图中提取中国传统色，以明确轮廓、几何块面与强烈明暗对比塑造人物。结合厚涂肌理，让古典韵味与现代视觉张力并存，而不是简单的扁平归纳或照片复刻。</p><div class=\"gallery\"><img src=\"nie-defense-06.png.webp\" alt=\"插画风格比较与硬切分风格定位\" loading=\"lazy\"><img src=\"nie-defense-32.png.webp\" alt=\"中国传统色系参考\" loading=\"lazy\"></div><h3>用符号承载角色叙事</h3><p>以符号修辞学作为分析框架，从造型、色彩、道具、场景与服饰五个维度提炼人物特征。花枝、面具、符箓与器物不仅是装饰，也参与角色身份和叙事氛围的表达；水墨山形与文字肌理统一系列的志怪意境。</p><div class=\"gallery character-analysis\"><figure><img src=\"nie-defense-40.png.webp\" alt=\"宁采臣角色的符号与设计解析\" loading=\"lazy\"><figcaption>宁采臣 / 角色设计解析</figcaption></figure><figure><img src=\"nie-defense-42.png.webp\" alt=\"姥姥角色的符号与设计解析\" loading=\"lazy\"><figcaption>姥姥 / 角色设计解析</figcaption></figure><figure><img src=\"nie-defense-46.png.webp\" alt=\"兰溪书生角色的符号与设计解析\" loading=\"lazy\"><figcaption>兰溪书生 / 角色设计解析</figcaption></figure><figure><img src=\"nie-defense-47.png.webp\" alt=\"宁妻角色的符号与设计解析\" loading=\"lazy\"><figcaption>宁妻 / 角色设计解析</figcaption></figure></div></section>\n<section><h2>04 / 遇到的问题与解决</h2><h3>资料分散，文学描述难以直接转为图像</h3><p>问题：原著、影视改编、服饰资料与实地场景提供的信息不同，缺少统一的视觉依据。解决：以造型、色彩、道具、场景和服饰分类整理文献，建立前期素材库；通过寺庙摄影、草图和动线记录补充空间布局信息，将实景作为构建虚构兰若寺的参考，而不是直接等同于原著场景。</p><h3>角色同质化与传统审美的现代转译</h3><p>问题：既有影视形象容易影响角色创作，中国传统色的搭配也需要契合人物性格。解决：结合问卷与案例分析确定硬切分风格，从传统画作提取色彩，通过明暗对冲、块面分割和厚涂肌理建立系列语言，再用角色专属服饰、道具与符号强化差异。</p><h3>单一插画难以承载完整体验</h3><p>问题：仅以插画呈现，文学设定与文化内涵不易展开。解决：用角色手册补充设计逻辑，用海报、明信片、书签与立牌拓展观看和收藏场景，并通过虚幻引擎场景探索空间氛围的呈现。</p></section>\n<section><h2>05 / 成品展示</h2><h3>角色与系列海报</h3><div class=\"gallery\">\n<img src=\"nie-xiaoqian-01-characters-web.jpg.webp\" alt=\"角色系列\" loading=\"lazy\"><img src=\"nie-xiaoqian-02-overview.png.webp\" alt=\"系列总览\" loading=\"lazy\">\n<img src=\"nie-poster-1.png.webp\" alt=\"角色海报一\" loading=\"lazy\"><img src=\"nie-poster-2.png.webp\" alt=\"角色海报二\" loading=\"lazy\"><img src=\"nie-poster-3.png.webp\" alt=\"角色海报三\" loading=\"lazy\"><img src=\"nie-poster-4.png.webp\" alt=\"角色海报四\" loading=\"lazy\"><img src=\"nie-poster-5-web.jpg.webp\" alt=\"角色海报五\" loading=\"lazy\"><img src=\"nie-poster-6-web.jpg.webp\" alt=\"角色海报六\" loading=\"lazy\"><img src=\"nie-poster-7-web.jpg.webp\" alt=\"角色海报七\" loading=\"lazy\"><img src=\"nie-poster-8-web.jpg.webp\" alt=\"角色海报八\" loading=\"lazy\">\n</div><h3>明信片延展</h3><div class=\"gallery\"><img src=\"nie-postcard-1-transparent.png.webp\" alt=\"明信片一\" loading=\"lazy\"><img src=\"nie-postcard-2-transparent.png.webp\" alt=\"明信片二\" loading=\"lazy\"><img src=\"nie-postcard-3-transparent.png.webp\" alt=\"明信片三\" loading=\"lazy\"></div><h3>角色立牌</h3><div class=\"gallery\"><img src=\"nie-stand-yecha-web-transparent.png.webp\" alt=\"夜叉立牌\" loading=\"lazy\"><img src=\"nie-stand-niexiaoqian-web-transparent.png.webp\" alt=\"聂小倩立牌\" loading=\"lazy\"><img src=\"nie-stand-ningcaicehng-web-transparent.png.webp\" alt=\"宁采臣立牌\" loading=\"lazy\"><img src=\"nie-stand-yanchixia-web-transparent.png.webp\" alt=\"燕赤霞立牌\" loading=\"lazy\"></div></section>\n</div>","identity.html":"<div class=\"process\">\n<section><h2>01 / 主题立项</h2><p>针对艺悦楼采光不足、拐角多、通道偏窄、出入口复杂及分区指引较弱的问题，围绕学生、教职工和外来访客建立设计定位，兼顾教学、研究、办公、展示与社交功能。</p><div class=\"gallery\"><img src=\"identity-report-09.jpg.webp\" alt=\"结课报告第9页\" loading=\"lazy\"><img src=\"identity-report-10.jpg.webp\" alt=\"结课报告第10页\" loading=\"lazy\"><img src=\"identity-report-11.jpg.webp\" alt=\"结课报告第11页\" loading=\"lazy\"><img src=\"identity-report-12.jpg.webp\" alt=\"结课报告第12页\" loading=\"lazy\"></div></section>\n<section><h2>02 / 制作过程</h2><p>通过案例研究与环境分析确定方向，制定图标、箭头、分区字母和数字清单，再展开室外、建筑入口与室内导视规划。以下展示结课报告的研究与元素设计记录。</p><div class=\"gallery\"><img src=\"identity-report-03.jpg.webp\" alt=\"结课报告第3页\" loading=\"lazy\"><img src=\"identity-report-04.jpg.webp\" alt=\"结课报告第4页\" loading=\"lazy\"><img src=\"identity-report-05.jpg.webp\" alt=\"结课报告第5页\" loading=\"lazy\"><img src=\"identity-report-06.jpg.webp\" alt=\"结课报告第6页\" loading=\"lazy\"><img src=\"identity-report-07.jpg.webp\" alt=\"结课报告第7页\" loading=\"lazy\"><img src=\"identity-report-08.jpg.webp\" alt=\"结课报告第8页\" loading=\"lazy\"><img src=\"identity-report-13.jpg.webp\" alt=\"结课报告第13页\" loading=\"lazy\"><img src=\"identity-report-14.jpg.webp\" alt=\"结课报告第14页\" loading=\"lazy\"><img src=\"identity-report-15.jpg.webp\" alt=\"结课报告第15页\" loading=\"lazy\"><img src=\"identity-report-16.jpg.webp\" alt=\"结课报告第16页\" loading=\"lazy\"></div></section>\n<section><h2>03 / 设计思路</h2><p>采用黑白简约风，以铝制结构与黑色镂空波点底板构成材料方案。文字、图标、楼层数字与箭头按模块组合，像搭积木一样适配门牌、悬挂标识、墙面标牌与立式导视。</p><div class=\"gallery\"><img src=\"identity-report-17.jpg.webp\" alt=\"结课报告第17页\" loading=\"lazy\"><img src=\"identity-report-18.jpg.webp\" alt=\"结课报告第18页\" loading=\"lazy\"><img src=\"identity-report-19.jpg.webp\" alt=\"结课报告第19页\" loading=\"lazy\"><img src=\"identity-report-20.jpg.webp\" alt=\"结课报告第20页\" loading=\"lazy\"><img src=\"identity-report-21.jpg.webp\" alt=\"结课报告第21页\" loading=\"lazy\"></div></section>\n<section><h2>04 / 问题与设计应对</h2><p>调研指出白色标识与白墙融合、分区指引偏弱、多入口容易迷失等问题。方案通过黑白对比、分区字母、箭头与功能图标组织信息。报告未记录实际安装或用户测试结果，因此不将设计意图写成已验证的改善效果。</p><div class=\"gallery\"></div></section>\n<section><h2>05 / 成品与场景效果</h2><p>八组原图与效果图对照展示导视在校园空间中的应用设想。保留原报告的对照关系；这些为方案效果图，并非施工落地照片。</p><div class=\"gallery\"><img src=\"identity-report-22.jpg.webp\" alt=\"结课报告第22页\" loading=\"lazy\"><img src=\"identity-report-23.jpg.webp\" alt=\"结课报告第23页\" loading=\"lazy\"><img src=\"identity-report-24.jpg.webp\" alt=\"结课报告第24页\" loading=\"lazy\"><img src=\"identity-report-25.jpg.webp\" alt=\"结课报告第25页\" loading=\"lazy\"><img src=\"identity-report-26.jpg.webp\" alt=\"结课报告第26页\" loading=\"lazy\"><img src=\"identity-report-27.jpg.webp\" alt=\"结课报告第27页\" loading=\"lazy\"><img src=\"identity-report-28.jpg.webp\" alt=\"结课报告第28页\" loading=\"lazy\"><img src=\"identity-report-29.jpg.webp\" alt=\"结课报告第29页\" loading=\"lazy\"></div></section>\n</div>"};
;

/* source: turntable-loader.js */
/* Load the original suitcase only when a project is opened. */
(()=>{
 let pending=null;
 const load=src=>new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src=src;
  const timeout=setTimeout(()=>{script.remove();reject(new Error('3D loading timed out'));},20000);
  script.onload=()=>{clearTimeout(timeout);resolve();};
  script.onerror=()=>{clearTimeout(timeout);script.remove();reject(new Error('3D loading failed'));};
  document.head.append(script);
 });
 window.ensureTurntable3D=()=>{
  if(pending)return pending;
  if(window.mountTurntable3D&&window.THREE&&window.createRedSuitcase)return Promise.resolve();
  if(!pending)pending=(async()=>{
   // Definitions are independent; fetch them together rather than in three round trips.
   await Promise.all([
    window.THREE?Promise.resolve():load('vendor/three.min.js'),
    window.createRedSuitcase?Promise.resolve():load('red-suitcase-model.js?v=4'),
    window.mountTurntable3D?Promise.resolve():load('suitcase-player.js?v=27')
   ]);
  })().catch(error=>{pending=null;throw error;});
  return pending;
 };
 // Browsing intent, not homepage load, prepares scripts. Do not mount a
 // renderer or build the model here; the selected project's host owns that.
 let scheduled=false;
 function warmOnIntent(event){
  if(scheduled||pending||window.mountTurntable3D||document.hidden||window.navigator?.connection?.saveData)return;
  if(!event.target.closest?.('.sleeve-front,.studio-disc button,.sleeve-hotspot,.sleeve-record,[data-overview-category]'))return;
  scheduled=true;
  const prepare=()=>{scheduled=false;if(!document.hidden&&!window.navigator?.connection?.saveData)window.ensureTurntable3D().catch(()=>{});};
  if(event.type==='pointerdown'){prepare();return;}
  if(window.requestIdleCallback)window.requestIdleCallback(prepare,{timeout:300});
  else setTimeout(prepare,150);
 }
 for(const type of ['pointerover','focusin','pointerdown'])document.addEventListener(type,warmOnIntent,{passive:true});
})();
;

/* source: suitcase-fallback.js */
/* Same suitcase, rendered from the original model; artwork remains project-specific. */
(()=>{
 let dispose=()=>{};
 window.disposeStaticSuitcase=()=>dispose();
 window.mountStaticSuitcase=(host,art)=>{
  dispose();host.classList.add('has-webgl','is-static-suitcase');
  const wrap=document.createElement('div');wrap.className='static-suitcase';
  wrap.innerHTML='<img class="static-case" src="suitcase-fallback.png" alt="猫头手提箱唱片机静态预览"><div class="static-art"><img alt="当前项目封面"></div>';
  host.append(wrap);const image=wrap.querySelector('.static-art img');
  const sync=()=>{image.src=art.src;};sync();
  const obs=new MutationObserver(sync);obs.observe(art,{attributes:true,attributeFilter:['src']});
  const resize=()=>{const s=Math.min(host.clientWidth/1000,host.clientHeight/900);wrap.style.transform='translate(-50%,-50%) scale('+s+')';};
  const ro=new ResizeObserver(resize);ro.observe(host);resize();
  dispose=()=>{obs.disconnect();ro.disconnect();wrap.remove();host.classList.remove('has-webgl','is-static-suitcase');dispose=()=>{};};
 };
})();
;

