/* source: hold-feedback.js */
/* Native press/release motion only: no fill, tint, progress stripe or detached overlay. */
(()=>{
 if(window.portfolioHoldFeedback)return;window.portfolioHoldFeedback=true;
 const selector='button,a[href],summary,[role="button"],input[type="button"],input[type="submit"]';
 const art='.sleeve-front,.sleeve-record,.sleeve-hotspot,.sleeve-side-trigger,.sleeve-spine-link,.studio-disc button,.overview-card';
 const reduced=matchMedia('(prefers-reduced-motion:reduce)');let current=null;
 function finish(){const s=current;if(!s)return;current=null;s.motion?.cancel();if(!reduced.matches&&s.target.isConnected)s.target.animate([{scale:.97},{scale:1}],{duration:160,easing:'cubic-bezier(.23,1,.32,1)'});}
 function begin(target,pointerId,x,y,key){finish();if(target.matches(art)||target.closest('.sleeve-model')||target.querySelector('img'))return;
  const s={target,pointerId,x,y,key,motion:null};current=s;
  if(!reduced.matches)s.motion=target.animate([{scale:1},{scale:.97}],{duration:100,fill:'forwards',easing:'ease-out'});

 }
 function getTarget(e){const target=e.target instanceof Element?e.target.closest(selector):null;return target&&!target.matches(':disabled,[aria-disabled="true"]')&&!target.closest('[inert]')?target:null;}
 document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const target=getTarget(e);if(target)begin(target,e.pointerId,e.clientX,e.clientY);},{capture:true,passive:true});
 document.addEventListener('pointermove',e=>{if(current?.pointerId===e.pointerId&&Math.hypot(e.clientX-current.x,e.clientY-current.y)>12)finish();},{passive:true});
 for(const event of ['pointerup','pointercancel'])document.addEventListener(event,e=>{if(current?.pointerId===e.pointerId)finish();},true);
 document.addEventListener('keydown',e=>{if(e.repeat||!['Enter',' '].includes(e.key))return;const target=getTarget(e);if(target)begin(target,null,0,0,e.key);},true);
 document.addEventListener('keyup',e=>{if(current?.key===e.key)finish();},true);
 for(const event of ['blur','pagehide'])window.addEventListener(event,finish);window.addEventListener('scroll',finish,{capture:true,passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)finish();});reduced.addEventListener('change',finish);
})();
;

/* source: jelly-navigation.js */
/* Native adaptation of the user-supplied React Bits JellyRadio motion reference. */
(()=>{
 const reduce=matchMedia('(prefers-reduced-motion:reduce)');
 document.querySelectorAll('.intro-navigation,.studio-navigation').forEach(nav=>{
  const items=[...nav.children].map(e=>e.matches('details')?e.querySelector('summary'):e).filter(e=>e?.matches('a,button,summary'));
  nav.classList.add('jelly-navigation');let selected=items[0],active=selected;const motions=new Map();
  function paint(target,instant=false){const chosen=items.indexOf(target);if(chosen<0)return;active=target;
   items.forEach((item,index)=>{item.dataset.jellyOn=String(item===target);const distance=Math.abs(index-chosen),direction=Math.sign(index-chosen);const x=direction*3.5,sx=item===target?1.055:.985,sy=item===target?1.035:.985;
    const from=getComputedStyle(item).transform;motions.get(item)?.cancel();const to='translateX('+x+'px) scale('+sx+','+sy+')';item.style.transform=to;
    if(instant||reduce.matches)return;
    const wide=item===target?'translateX(0px) scale(1.13,.95)':'translateX('+(x*1.4)+'px) scale(.97,.99)';
    motions.set(item,item.animate([{transform:from==='none'?'none':from},{transform:wide,offset:.33},{transform:item===target?'translateX(0) scale(1.035,1.07)':'translateX('+x+'px) scale(.99,.98)',offset:.7},{transform:to}],{duration:430+distance*18,delay:distance*14,easing:'cubic-bezier(.22,.7,.25,1)'}));
   });
  }
  items.forEach((item,index)=>{item.addEventListener('pointerenter',()=>{if(active!==item)paint(item);});item.addEventListener('focus',()=>paint(item));item.addEventListener('click',()=>{selected=item;paint(item);});item.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowRight'?1:-1)+items.length)%items.length].focus();});});
  nav.addEventListener('pointerleave',()=>paint(items.includes(document.activeElement)?document.activeElement:selected));nav.addEventListener('focusout',()=>requestAnimationFrame(()=>{if(!nav.contains(document.activeElement))paint(selected);}));paint(selected,true);
 });
})();
;

/* source: overview-cd-cases.js */
/* Transparent CD cases keep category links and filters intact. */
(()=>{
 const projects=window.albumProjects;if(!projects)return;
 const covers={graphic:'lin-chang-fa-hui-exhibition-poster.png.webp',identity:'wayfinding-01-system-web-transparent.png.webp',keyvisual:'imprint-static-01.png.webp',packaging:'half-a-whisper/brand-packaging-merchandise-final.png.webp',uiux:'green-book-cover-cutout.png.webp',extended:'wonder-journey-cover-cutout.png.webp',illustration:'nie-xiaoqian-01-characters-web.jpg.webp'};
 document.querySelectorAll('.overview-card[data-overview-category]').forEach((card,index)=>{
  const key=card.dataset.overviewCategory,p=projects[key];if(!p)return;card.classList.add('cd-case-card');
  const shell=document.createElement('span');shell.className='overview-cd-case';shell.setAttribute('aria-hidden','true');
  const hinge=document.createElement('span');hinge.className='cd-case-hinge';
  const tray=document.createElement('span');tray.className='cd-case-tray';
  const disc=document.createElement('span');disc.className='cd-case-disc';
  const eyebrow=document.createElement('small');eyebrow.className='cd-disc-eyebrow';eyebrow.textContent=String(index+1).padStart(2,'0')+' / DESIGN COLLECTION';
  const title=document.createElement('strong');title.className='cd-disc-title';title.textContent=p.title;
  const art=document.createElement('span');art.className='cd-disc-art';const image=document.createElement('img');image.src=covers[key]||p.series[0].cover||p.series[0].images[0];image.alt='';image.loading='lazy';image.decoding='async';art.append(image);
  const hub=document.createElement('span');hub.className='cd-disc-hub';const count=document.createElement('em');count.className='cd-disc-count';count.textContent=p.series.length+' PROJECTS';
  disc.append(eyebrow,title,art,hub,count);tray.append(disc);
  const gloss=document.createElement('span');gloss.className='cd-case-gloss';for(const edge of ['top','bottom']){const clip=document.createElement('span');clip.className='cd-case-clip cd-case-clip-'+edge;shell.append(clip);}
  shell.append(hinge,tray,gloss);
  const caption=document.createElement('span');caption.className='cd-case-caption';const number=document.createElement('span');number.textContent=String(index+1).padStart(2,'0');const heading=document.createElement('h2');heading.textContent=p.title;const total=document.createElement('small');total.textContent=String(p.series.length).padStart(2,'0')+' PROJECTS';caption.append(number,heading,total);
  card.replaceChildren(shell,caption);
 });
})();
;
